// 认证中间件 -> 授权中间件 -> 资源处理器：401 / 403 / 200 的状态码映射
const crypto = require('crypto');
const SECRET = Buffer.from('ch06-mw-demo-secret');

function b64urlEncode(input) {
  const buf = Buffer.isBuffer(input) ? input : Buffer.from(String(input), 'utf8');
  return buf.toString('base64').replace(/=+$/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}
function sign(payload) {
  const h = b64urlEncode(JSON.stringify({ alg: 'HS256' }));
  const p = b64urlEncode(JSON.stringify(payload));
  const s = b64urlEncode(crypto.createHmac('sha256', SECRET).update(h + '.' + p).digest());
  return h + '.' + p + '.' + s;
}
function decodePayload(token) {
 try {
    const pad = token.split('.')[1].length % 4 === 0 ? '' : '='.repeat(4 - (token.split('.')[1].length % 4));
    return JSON.parse(Buffer.from(token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/') + pad, 'base64').toString('utf8'));
  } catch (e) { return null; }
}

// ① 认证中间件：无/坏 token -> 401，并把 user 挂到 ctx
function authenticate(ctx) {
  const auth = ctx.headers.authorization;
  if (!auth || !auth.startsWith('Bearer ')) return { status: 401, body: 'unauthenticated' };
  const user = decodePayload(auth.slice(7));
  if (!user) return { status: 401, body: 'invalid-token' };
  ctx.user = user;
  return null;
}
// ② 授权中间件：已认证但权限不足 -> 403
function authorize(permission) {
  return (ctx) => (ctx.user.permissions.indexOf(permission) >= 0)
    ? null
    : { status: 403, body: 'forbidden' };
}
// ③ 资源处理器
function handler(ctx) { return { status: 200, body: 'ok:' + ctx.user.sub }; }

function run(handlers, ctx) {
  for (const h of handlers) {
    const res = h(ctx);
    if (res) return res;
  }
  return handler(ctx);
}

const adminToken = 'Bearer ' + sign({ sub: 'u1', permissions: ['article:write'] });
const plainToken = 'Bearer ' + sign({ sub: 'u2', permissions: ['article:read'] });
const chain = [authenticate, authorize('article:write')];

function show(name, headers) {
  const r = run(chain, { headers, user: null });
  console.log(name + ' status=' + r.status + ' body=' + r.body);
}
show('no_token', {});
show('bad_scheme', { authorization: 'Token abc' });
show('valid_but_no_perm', { authorization: plainToken });
show('valid_with_perm', { authorization: adminToken });
